mapper.insert:
/* USE : SmsMenuAuthMapper.insertSmsMenuAuth */
MERGE INTO TB_WB_AUTHOR_USER_IN_EX
USING DUAL
ON  (
            USER_ID     = #{userId}
        AND RESRCE_CD   = #{resrceCd}
    )
WHEN MATCHED THEN
UPDATE
SET
        INCLD_EXCLD_FG  = 'I'
,       USE_YN          = 'Y'
,       MOD_DT          = #{modDt}
,       MOD_ID          = #{modId}
WHEN NOT MATCHED THEN
INSERT
(
        USER_ID
,       AUTHOR_PRODC_FG
,       RESRCE_CD
,       INCLD_EXCLD_FG
,       USE_YN
,       REG_DT
,       REG_ID
,       MOD_DT
,       MOD_ID
,       REMARK
,       LOGIN_FG
)
VALUES
(
        #{userId}
,       #{authorProdcFg}
,       #{resrceCd}
,       'I'
,       'Y'
,       #{regDt}
,       #{regId}
,       #{modDt}
,       #{modId}
,       #{remark}
,       'W'
)

mapper.delete:
/* USE : SmsMenuAuthMapper.deleteSmsMenuAuth */
DELETE
FROM    TB_WB_AUTHOR_USER_IN_EX
WHERE   USER_ID     =   #{userId}
AND     RESRCE_CD   =   #{resrceCd}
